import pytest
from review.out.astra_scratch import test_r21 as prev
from review.out.astra_scratch.test_r27 import mature_failed_fixture

@pytest.mark.parametrize('failure', ['packet', 'forecast'])
@pytest.mark.parametrize('header', ['header_15', 'header_15b', 'header_15c'])
def test_cabeceras_con_semana_fallida(tmp_path, monkeypatch, failure, header):
    raw, market, data = mature_failed_fixture(tmp_path, monkeypatch, failure)
    asm = prev.load('assemble_backtest_reports')
    fn = getattr(asm, header)
    text = fn(data) if header == 'header_15' else fn(data, data)
    assert 'invalid:archive' in text
